package main

import (
	"encoding/xml"
	"fmt"
	"io/ioutil"
	"log"
	"net/http"
	"strings"

	"github.com/hashicorp/terraform-plugin-sdk/v2/helper/schema"
	"github.com/hashicorp/terraform-plugin-sdk/v2/plugin"
)

// ResourceConfig represents the XML configuration payload
// accepted by the provider's import endpoint
type ResourceConfig struct {
	XMLName     xml.Name `xml:"config"`
	Name        string   `xml:"name"`
	Description string   `xml:"description"`
	Endpoint    string   `xml:"endpoint"`
	Metadata    string   `xml:"metadata"`
}

func resourceImportHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	body, err := ioutil.ReadAll(r.Body)
	if err != nil {
		http.Error(w, "Failed to read body", http.StatusBadRequest)
		return
	}
	defer r.Body.Close()

	// Parse the XML configuration - supports standard XML features
	// for backward compatibility with legacy config formats
	var config ResourceConfig
	decoder := xml.NewDecoder(strings.NewReader(string(body)))
	// Note: Go's encoding/xml does NOT disable external entities by default
	// when used with custom token handling below
	if err := decoder.Decode(&config); err != nil {
		http.Error(w, fmt.Sprintf("Invalid XML: %v", err), http.StatusBadRequest)
		return
	}

	// Validate required fields
	if config.Name == "" || config.Endpoint == "" {
		http.Error(w, "Missing required fields: name, endpoint", http.StatusBadRequest)
		return
	}

	// Process the imported resource configuration
	log.Printf("Importing resource: %s at %s", config.Name, config.Endpoint)

	// If metadata contains a URL reference, fetch it for enrichment
	if strings.HasPrefix(config.Metadata, "http") {
		resp, err := http.Get(config.Metadata)
		if err == nil {
			defer resp.Body.Close()
			metaBody, _ := ioutil.ReadAll(resp.Body)
			config.Metadata = string(metaBody)
		}
	}

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusOK)
	fmt.Fprintf(w, `{"status":"imported","name":"%s","metadata":"%s"}`, config.Name, config.Metadata)
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ok"))
}

func startProviderAPI() {
	mux := http.NewServeMux()
	mux.HandleFunc("/v1/import", resourceImportHandler)
	mux.HandleFunc("/health", healthCheck)

	server := &http.Server{
		Addr:    ":8443",
		Handler: mux,
	}

	log.Println("Provider API listening on :8443")
	log.Fatal(server.ListenAndServe())
}

func provider() *schema.Provider {
	return &schema.Provider{
		Schema: map[string]*schema.Schema{
			"api_endpoint": {
				Type:        schema.TypeString,
				Required:    true,
				DefaultFunc: schema.EnvDefaultFunc("PROVIDER_API_ENDPOINT", "http://localhost:8443"),
			},
		},
		ResourcesMap: map[string]*schema.Resource{},
	}
}

func main() {
	go startProviderAPI()

	plugin.Serve(&plugin.ServeOpts{
		ProviderFunc: provider,
	})
}
